        "tank" to 55,
        "tridol1" to 34,
        "tridol2" to 16,
        "tridol3" to 30,
        "zoom1" to 76,
        "zoom2" to 72,
        "zoom3" to 72,
        "zoom4" to 45,
        "zoom5" to 66,
        "zoom6" to 89,
        "zoom7" to 24
    )

    fun load(name: String): Array<Vector2> {
        val text = coordinates[name] ?: error("Unknown pinned polygon fixture: $name")
        val points = text.split(';').map { pair ->
            val values = pair.split(' ')
            Vector2(values[0].toDouble(), values[1].toDouble())
        }.toTypedArray()
        check(points.size == vertexCounts[name])
        return points
    }
}
